package dev.queiroz.relay.status.web;

import dev.queiroz.relay.api.pagination.*;
import dev.queiroz.relay.ingestion.application.*;
import dev.queiroz.relay.ingestion.domain.TenantId;
import dev.queiroz.relay.ingestion.web.UnauthorizedException;
import dev.queiroz.relay.status.application.StatusStore;
import org.springframework.web.bind.annotation.*;
import java.time.Instant; import java.util.*;

@RestController @RequestMapping("/v1") public class StatusController {
 private static final int DEFAULT_LIMIT=20,MAX_LIMIT=100; private final StatusStore store; private final ApiKeyService keys; private final TenantRateLimitService limits; private final CursorCodec cursors;
 public StatusController(StatusStore store,ApiKeyService keys,TenantRateLimitService limits,CursorCodec cursors){this.store=store;this.keys=keys;this.limits=limits;this.cursors=cursors;}
 @GetMapping("/events") public Page<EventResponse> events(@RequestHeader(value="X-Relay-Api-Key",required=false)String key,@RequestParam Map<String,String> q){TenantId t=tenant(key); Query p=query(q); KeysetCursor c=p.cursor==null?null:cursors.decode(p.cursor,"v1/events",t);var rows=store.events(t,c,p.limit+1);return page(rows,p.limit,x->cursors.encode("v1/events",t,new KeysetCursor(x.createdAt(),x.id())),EventResponse::new);}
 @GetMapping("/events/{id}") public EventResponse event(@RequestHeader(value="X-Relay-Api-Key",required=false)String key,@PathVariable UUID id){return store.event(tenant(key),id).map(EventResponse::new).orElseThrow(StatusNotFoundException::new);}
 @GetMapping("/events/{id}/deliveries") public Page<DeliveryResponse> deliveries(@RequestHeader(value="X-Relay-Api-Key",required=false)String key,@PathVariable UUID id,@RequestParam Map<String,String> q){TenantId t=tenant(key);if(store.event(t,id).isEmpty())throw new StatusNotFoundException();Query p=query(q);KeysetCursor c=p.cursor==null?null:cursors.decode(p.cursor,"v1/events/"+id+"/deliveries",t);var rows=store.deliveries(t,id,c,p.limit+1);return page(rows,p.limit,x->cursors.encode("v1/events/"+id+"/deliveries",t,new KeysetCursor(x.createdAt(),x.id())),DeliveryResponse::new);}
 @GetMapping("/deliveries/{id}") public DeliveryResponse delivery(@RequestHeader(value="X-Relay-Api-Key",required=false)String key,@PathVariable UUID id){return store.delivery(tenant(key),id).map(DeliveryResponse::new).orElseThrow(StatusNotFoundException::new);}
 @GetMapping("/deliveries/{id}/attempts") public Page<AttemptResponse> attempts(@RequestHeader(value="X-Relay-Api-Key",required=false)String key,@PathVariable UUID id,@RequestParam Map<String,String> q){TenantId t=tenant(key);if(store.delivery(t,id).isEmpty())throw new StatusNotFoundException();Query p=query(q);AttemptCursor c=p.cursor==null?null:cursors.decodeAttempt(p.cursor,"v1/deliveries/"+id+"/attempts",t);var rows=store.attempts(t,id,c,p.limit+1);boolean more=rows.size()>p.limit;var data=(more?rows.subList(0,p.limit):rows).stream().map(AttemptResponse::new).toList();return new Page<>(data,new PageInfo(more,more?cursors.encodeAttempt("v1/deliveries/"+id+"/attempts",t,new AttemptCursor(rows.get(p.limit-1).sequenceNumber(),rows.get(p.limit-1).id())):null));}
 private TenantId tenant(String k){TenantId t=keys.authenticate(k).orElseThrow(UnauthorizedException::new);if(!limits.allowRequest(t))throw new RateLimitExceededException();return t;}
 private Query query(Map<String,String>q){if(!Set.of("limit","cursor").containsAll(q.keySet()))throw new StatusRequestException();int l=DEFAULT_LIMIT;try{if(q.containsKey("limit"))l=Integer.parseInt(q.get("limit"));}catch(RuntimeException e){throw new StatusRequestException();}if(l<1||l>MAX_LIMIT||q.get("cursor")!=null&&q.get("cursor").isBlank())throw new StatusRequestException();return new Query(l,q.get("cursor"));}
 private <S,R> Page<R> page(List<S> rows,int l,java.util.function.Function<S,String> next,java.util.function.Function<S,R> map){boolean more=rows.size()>l;List<S> data=more?rows.subList(0,l):rows;return new Page<>(data.stream().map(map).toList(),new PageInfo(more,more?next.apply(data.getLast()):null));}
 private record Query(int limit,String cursor){} public record Page<T>(List<T> data,PageInfo page){} public record PageInfo(boolean hasMore,String nextCursor){} public record EventResponse(UUID id,String type,String status,Instant createdAt){EventResponse(StatusStore.EventSummary x){this(x.id(),x.type(),x.status(),x.createdAt());}} public record DeliveryResponse(UUID id,UUID eventId,UUID endpointId,String state,int attemptsCount,Instant nextAttemptAt,Instant createdAt,Instant updatedAt){DeliveryResponse(StatusStore.DeliverySummary x){this(x.id(),x.eventId(),x.endpointId(),x.state(),x.attemptsCount(),x.nextAttemptAt(),x.createdAt(),x.updatedAt());}} public record AttemptResponse(UUID id,UUID deliveryId,int sequenceNumber,Instant startedAt,Instant finishedAt,String outcome,Integer responseStatus,String sanitizedErrorCode){AttemptResponse(StatusStore.AttemptSummary x){this(x.id(),x.deliveryId(),x.sequenceNumber(),x.startedAt(),x.finishedAt(),x.outcome(),x.responseStatus(),x.sanitizedErrorCode());}}
}
